import { cn } from "cn";
import { motion } from "motion/react";
import type { Transition } from "motion/react";
import type { JSX } from "react";

export interface TextShimmerWaveProps {
  children: string;
  as?: React.ElementType;
  className?: string;
  duration?: number;
  baseColor?: string;
  shimmerColor?: string;
  zDistance?: number;
  xDistance?: number;
  yDistance?: number;
  spread?: number;
  scaleDistance?: number;
  rotateYDistance?: number;
  transition?: Transition;
  style?: React.CSSProperties;
}

export function TextShimmerWave({
  children,
  as: Component = "p",
  className,
  duration = 1,
  baseColor,
  shimmerColor,
  zDistance = 10,
  xDistance = 2,
  yDistance = -2,
  spread = 1,
  scaleDistance = 1.1,
  rotateYDistance = 10,
  transition,
  style,
}: TextShimmerWaveProps) {
  const MotionComponent = motion.create(
    Component as keyof JSX.IntrinsicElements
  );

  return (
    <MotionComponent
      className={cn("relative inline-block [perspective:500px]", className)}
      style={
        {
          ...style,
          "--base-color":
            baseColor ?? "color-mix(in oklab, currentColor 55%, transparent)",
          "--base-gradient-color": shimmerColor ?? "currentColor",
        } as React.CSSProperties
      }
    >
      {[...children].map((char, i) => {
        const delay = (i * duration * (1 / spread)) / children.length;

        return (
          <motion.span
            key={i}
            className={cn(
              "inline-block whitespace-pre [transform-style:preserve-3d]"
            )}
            initial={{
              color: "var(--base-color)",
              rotateY: 0,
              scale: 1,
              translateZ: 0,
            }}
            animate={{
              color: [
                "var(--base-color)",
                "var(--base-gradient-color)",
                "var(--base-color)",
              ],
              rotateY: [0, rotateYDistance, 0],
              scale: [1, scaleDistance, 1],
              translateX: [0, xDistance, 0],
              translateY: [0, yDistance, 0],
              translateZ: [0, zDistance, 0],
            }}
            transition={{
              delay,
              duration,
              ease: "easeInOut",
              repeat: Infinity,
              repeatDelay: (children.length * 0.05) / spread,
              ...transition,
            }}
          >
            {char}
          </motion.span>
        );
      })}
    </MotionComponent>
  );
}

